window.docContents[118].resolve({"/2___-Basic-notions-of-representation-theory/#chapter-02":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory","header":"2. Basic notions of representation theory","id":"/2___-Basic-notions-of-representation-theory/#chapter-02"},"/2___-Basic-notions-of-representation-theory/2___16___-Problems-on-Lie-algebras/Section-2___16___-Problems-on-Lie-algebras-___-heading/#Chapter2___Discussion_2___16_heading___heading-1":{"contents":"","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.16. Problems on Lie algebras\tSection 2.16: Problems on Lie algebras — heading","header":"2.16. Problems on Lie algebras","id":"/2___-Basic-notions-of-representation-theory/2___16___-Problems-on-Lie-algebras/Section-2___16___-Problems-on-Lie-algebras-___-heading/#Chapter2___Discussion_2___16_heading___heading-1"},"/3___-General-results-of-representation-theory/3___5___-Finite-dimensional-algebras/Sum-of-squares-of-dimensions-of-irreducibles-bounded-by-dim-A/#Chapter3___Corollary3___5___5___heading-1":{"contents":"Proof. As \\dim \\operatorname{End} V_i = (\\dim V_i)^2, Theorem 3.5.4 implies that \\dim A - \\dim \\operatorname{Rad}(A) = \\sum_i \\dim \\operatorname{End} V_i = \\sum_i (\\dim V_i)^2. As \\dim \\operatorname{Rad}(A) \\geq 0, \\sum_i (\\dim V_i)^2 \\leq \\dim A. \\square\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.5. Finite dimensional algebras\tSum of squares of dimensions of irreducibles bounded by dim A","header":"3.5. Finite dimensional algebras","id":"/3___-General-results-of-representation-theory/3___5___-Finite-dimensional-algebras/Sum-of-squares-of-dimensions-of-irreducibles-bounded-by-dim-A/#Chapter3___Corollary3___5___5___heading-1"},"/4___-Representations-of-finite-groups___-Basic-results/4___12___-Problems/Decomposition-of-representations-of-A_5-on-icosahedron/#Chapter4___Problem4___12___5":{"contents":"Problem 4.12.5. Let I be the set of vertices of a regular icosahedron (|I| = 12). Let F(I) be the space of complex functions on I. Recall that the group G = A_5 of even permutations of five items acts on the icosahedron, so we have a 12-dimensional representation of G on F(I).\n(a) Decompose this representation in a direct sum of irreducible representations (i.e., find the multiplicities of occurrence of all irreducible representations).\n\n(b) Do the same for the representation of G on the space of functions on the set of faces and the set of edges of the icosahedron.\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.12. Problems\tDecomposition of representations of A_5 on icosahedron","header":"Decomposition of representations of A_5 on icosahedron","id":"/4___-Representations-of-finite-groups___-Basic-results/4___12___-Problems/Decomposition-of-representations-of-A_5-on-icosahedron/#Chapter4___Problem4___12___5"},"/4___-Representations-of-finite-groups___-Basic-results/4___13___-Historical-interlude___-William-Rowan-Hamilton___s-quaternion-of-geometry___-algebra___-metaphysics___-and-poetry/Section-4___13___-Historical-interlude-___-William-Rowan-Hamilton___s-quaternion-of-geometry___-algebra___-metaphysics___-and-poetry/#Chapter4___Discussion_4___13":{"contents":"\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.13. Historical interlude: William Rowan Hamilton's quaternion of geometry, algebra, metaphysics, and poetry\tSection 4.13: Historical interlude — William Rowan Hamilton's quaternion of geometry, algebra, metaphysics, and poetry","header":"Section 4.13: Historical interlude — William Rowan Hamilton's quaternion of geometry, algebra, metaphysics, and poetry","id":"/4___-Representations-of-finite-groups___-Basic-results/4___13___-Historical-interlude___-William-Rowan-Hamilton___s-quaternion-of-geometry___-algebra___-metaphysics___-and-poetry/Section-4___13___-Historical-interlude-___-William-Rowan-Hamilton___s-quaternion-of-geometry___-algebra___-metaphysics___-and-poetry/#Chapter4___Discussion_4___13"},"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/Algebraic-_LPAR_rational___-polynomial_RPAR_-representation-of-GL_LPAR_V_RPAR_/#Chapter5___Definition5___23___1":{"contents":"Definition 5.23.1. We say that a finite dimensional representation Y of GL(V) is algebraic (or rational, or polynomial) if its matrix elements are polynomial functions of the entries of g, g^{-1}, g \\in GL(V) (i.e., belong to k[g_{ij}][1/\\det(g)]).\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.23. Algebraic representations of $GL(V)$\tAlgebraic (rational, polynomial) representation of GL(V)","header":"Algebraic (rational, polynomial) representation of GL(V)","id":"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/Algebraic-_LPAR_rational___-polynomial_RPAR_-representation-of-GL_LPAR_V_RPAR_/#Chapter5___Definition5___23___1"},"/7___-Introduction-to-categories/7___1___-The-definition-of-a-category/Examples-of-categories/#Chapter7___Example7___1___3":{"contents":"Example 7.1.3. 1. The category Sets of sets (morphisms are arbitrary maps).\n\n2. The categories Groups, Rings (morphisms are homomorphisms).3. The category \\mathbf{Vect}_k of vector spaces over a field k (morphisms are linear maps).4. The category \\operatorname{Rep}(A) of representations of an algebra A (morphisms are homomorphisms of representations). It is also denoted by A-mod (the category of left A-modules).5. The category of topological spaces (morphisms are continuous maps).6. The homotopy category of topological spaces (morphisms are homotopy classes of continuous maps).\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.1. The definition of a category\tExamples of categories","header":"Examples of categories","id":"/7___-Introduction-to-categories/7___1___-The-definition-of-a-category/Examples-of-categories/#Chapter7___Example7___1___3"},"/7___-Introduction-to-categories/7___7___-Abelian-categories/Section-7___7___-Abelian-categories/#Chapter7___Introduction_7___7":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.7. Abelian categories\tSection 7.7: Abelian categories","header":"Section 7.7: Abelian categories","id":"/7___-Introduction-to-categories/7___7___-Abelian-categories/Section-7___7___-Abelian-categories/#Chapter7___Introduction_7___7"}});
